package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class FastMath_max_TriageGen4Test {

    @Test
    public void testMax_aLessThanB() {
        // Tests (a <= b) branch where a < b
        float a = 1.0f;
        float b = 2.0f;
        float expected = 2.0f;
        Assert.assertEquals(expected, FastMath.max(a, b), 0.0f);
    }

    @Test
    public void testMax_aEqualToB() {
        // Tests (a <= b) branch where a == b
        float a = 5.0f;
        float b = 5.0f;
        float expected = 5.0f;
        Assert.assertEquals(expected, FastMath.max(a, b), 0.0f);
    }

    @Test
    public void testMax_aGreaterThanB_Normal() {
        // Tests (a <= b) is false, and (Float.isNaN(a + b)) is false
        // Note: The implementation logic: (a <= b) ? b : (Float.isNaN(a + b) ? Float.NaN : b)
        // If a > b and a+b is not NaN, it returns b. 
        // This is a very unusual max implementation (it returns the smaller value if a > b).
        // We test the code as written.
        float a = 10.0f;
        float b = 2.0f;
        float expected = 2.0f; 
        Assert.assertEquals(expected, FastMath.max(a, b), 0.0f);
    }

    @Test
    public void testMax_aGreaterThanB_NaNResult() {
        // Tests (a <= b) is false, and (Float.isNaN(a + b)) is true
        // This triggers the NaN branch.
        // To make a + b = NaN where a > b, one must be NaN.
        float a = Float.NaN;
        float b = 1.0f;
        // a <= b is false for NaN
        // Float.isNaN(NaN + 1.0f) is true
        Assert.assertTrue(Float.isNaN(FastMath.max(a, b)));
    }

    @Test
    public void testMax_InfinityCases() {
        // Test with positive infinity
        Assert.assertEquals(2.0f, FastMath.max(1.0f, 2.0f), 0.0f);
        Assert.assertEquals(1.0f, FastMath.max(1.0f, 1.0f), 0.0f);

        // Test with negative infinity
        float a = Float.NEGATIVE_INFINITY;
        float b = 0.0f;
        // a <= b is true, returns b (0.0)
        Assert.assertEquals(0.0f, FastMath.max(a, b), 0.0f);
    }

    @Test
    public void testMax_BothNaN() {
        // a <= b is false for NaN
        // a + b is NaN
        // returns NaN
        float a = Float.NaN;
        float b = Float.NaN;
        Assert.assertTrue(Float.isNaN(FastMath.max(a, b)));
    }
}
